const { withAppBuildGradle } = require('expo/config-plugins');

// Generated by prebuild. Credentials stay in user Gradle properties or environment.
const signing = `
// @generated begin techstore-local-release-signing
def techstoreSigningKeys = ['TECHSTORE_RELEASE_STORE_FILE', 'TECHSTORE_RELEASE_STORE_PASSWORD',
                           'TECHSTORE_RELEASE_KEY_ALIAS', 'TECHSTORE_RELEASE_KEY_PASSWORD']
def techstoreSigningValues = techstoreSigningKeys.collectEntries { key -> [(key): findProperty(key)] }
def techstoreSigningReady = techstoreSigningValues.values().every { it != null && !it.toString().isEmpty() }
android {
    signingConfigs {
        techstoreRelease {
            if (techstoreSigningReady) {
                storeFile file(techstoreSigningValues.TECHSTORE_RELEASE_STORE_FILE)
                storePassword techstoreSigningValues.TECHSTORE_RELEASE_STORE_PASSWORD.toString()
                keyAlias techstoreSigningValues.TECHSTORE_RELEASE_KEY_ALIAS.toString()
                keyPassword techstoreSigningValues.TECHSTORE_RELEASE_KEY_PASSWORD.toString()
            }
        }
    }
    buildTypes {
        release {
            // Never silently publish a release signed with the template debug key.
            signingConfig techstoreSigningReady ? signingConfigs.techstoreRelease : null
        }
    }
}
def validateTechstoreSigning = tasks.register('validateTechstoreSigning') {
    doLast {
        if (!techstoreSigningReady) {
            throw new GradleException('TechStore release signing is missing. Configure the four TECHSTORE_RELEASE_* user Gradle properties; never put passwords in the repository.')
        }
        def signingFile = file(techstoreSigningValues.TECHSTORE_RELEASE_STORE_FILE)
        if (!signingFile.isFile() || signingFile.name == 'debug.keystore'
            || techstoreSigningValues.TECHSTORE_RELEASE_KEY_ALIAS.toString() == 'androiddebugkey') {
            throw new GradleException('TechStore requires an existing release keystore and release alias, not the template debug key.')
        }
    }
}
tasks.configureEach { task ->
    if (task.name == 'preReleaseBuild') task.dependsOn(validateTechstoreSigning)
}
// @generated end techstore-local-release-signing
`;

module.exports = config => withAppBuildGradle(config, mod => {
    if (mod.modResults.language !== 'groovy') throw new Error('TechStore local signing requires the Expo Groovy template.');
    mod.modResults.contents = mod.modResults.contents.replace(
        /\n\/\/ @generated begin techstore-local-release-signing[\s\S]*?\/\/ @generated end techstore-local-release-signing\n?/g, ''
    ) + signing;
    return mod;
});
